from lib import *
S = SS('t31')
steps = [
    step("汇总校验的盲区。两个库各 100 万行。在 B 里改两行:一行金额 +7、另一行金额 -7,互相抵消。A 的 count = 1000000、sum(amount) = 587881504,B 的 count 和 sum 完全一样——count 和 sum 认为“一致”。逐行哈希再异或(bit_xor(crc32(id|amount|status))):A = 2763208693,B = 3801738515,不同,发现了。只比总数的校验会漏掉这种“一加一减”。", t=tl(S(1)), mark=lidx(S(1), '逐行哈希再异或'), done=lidx(S(1), 'A:count = 1000000'), b=bars([['count 是否不同', 0, '0(相同)'], ['sum(amount) 是否不同', 0, '0(相同)'], ['逐行哈希异或是否不同', 1, '1(不同)']], 1, done=[2], mark=[0, 1]), kv=KV([['count、sum', '一加一减时 A、B 完全相同'], ['逐行哈希 bit_xor', '2763208693 ≠ 3801738515'], ['结论', '总数校验会漏抵消的错误']], ['结论'])),
    step("分桶校验和对比全量比较。A、B 各 100 万行,有 50 处差异(20 行金额不同、15 行 B 缺失、15 行 B 多出)。全量比较(两边所有行拉出来比):3.6 s,传输 31.4 MiB,报出 50 处,全部是真差异,漏报 0。分桶校验和(每 1000 行一个桶,在数据库内部算 count 和行哈希的异或,只把每个桶的校验和拿出来比,有差异的桶再拉出行):1.67 s(校验和 1.01 s、下钻 0.66 s),传输 1095 KiB(校验和 38 KiB、下钻 1057 KiB),同样报出 50 处、漏报 0。有差异的桶 34 个,共 1002 个桶。校验和在数据库内部算,只有每个桶的 (桶号, count, 哈希) 离开数据库。", t=tl(S(2)), mark=lidx(S(2), '分桶校验和'), done=lidx(S(2), '全量比较', '有差异的桶'), b=bars([['全量比较 传输 MiB', 31.4, '31.4'], ['分桶校验 传输 MiB', 1.07, '1.07(1095 KiB)'], ['全量比较 用时 s', 3.6, '3.6'], ['分桶校验 用时 s', 1.67, '1.67']], 32, cur=[0, 2], mark=[1, 3]), kv=KV([['全量比较', '3.6 s,31.4 MiB,50 / 50'], ['分桶校验', '1.67 s,1095 KiB,50 / 50'], ['做法', '库内算校验和,只下钻有差异的桶']], ['做法'])),
    step("不同的汇总方式能发现哪几类差异。每类差异测 60 次,先取 B 在 id 1 到 20000 这一段的各种校验值,造出一种差异后再取一次,看值有没有变。金额 +1:count 0 / 60,sum(amount) 60 / 60,bit_xor 60 / 60,行哈希 sum 60 / 60,SHA-256 链 60 / 60。少一行:各种都是 60 / 60。一加一减(抵消):count 0 / 60,sum(amount) 0 / 60,bit_xor 58 / 60,行哈希 sum 和 SHA-256 链 60 / 60。只改状态(金额不变):count 0 / 60,sum(amount) 0 / 60,其余 60 / 60。bit_xor 在“一加一减”上漏了 2 次,我的解释是 CRC32 线性,两处改动的比特差异模式相同时哈希差相同(这个解释没有单独验证)。", t=tl(S(3)), mark=lidx(S(3), '一加一减(抵消)'), done=lidx(S(3), '金额 +1', '少一行', '状态被改'), b=bars([['count 发现“一加一减”', 0, '0 / 60'], ['sum(amount) 发现“一加一减”', 0, '0 / 60'], ['bit_xor 发现“一加一减”', 58, '58 / 60'], ['行哈希 sum 发现“一加一减”', 60, '60 / 60']], 60, mark=[0, 1], cur=[2], done=[3]), kv=KV([['count / sum(amount)', '发现不了抵消和只改状态'], ['bit_xor', '漏了 2 / 60 次一加一减'], ['行哈希 sum、SHA-256 链', '四类全部 60 / 60']], ['bit_xor'])),
    step("增量校验的提交顺序陷阱。检查器每 100 ms 跑一次,只看 updated_at 落在“上次检查开始之后”的行;updated_at 是语句执行时的时刻、不是提交时刻。300 个事务在 3 秒里随机开始,每个事务改一行后持有一段时间才提交(70% 持有 0 到 20 ms、25% 持有 20 到 250 ms、5% 持有 250 到 900 ms)。窗口不重叠:300 个改动里 101 个一直没被检查到(漏报 33.7%);窗口往前重叠 100 ms:40 个(13.3%);重叠 300 ms:9 个(3.0%);重叠 1000 ms:0 个。提交得晚的事务的行,在被查到之前就滑出了窗口;重叠的长度要大于最长事务的持有时间。更稳的是用提交顺序单调的位点(binlog 位点、LSN、自增版本号)。", t=tl(S(4)), mark=lidx(S(4), '不重叠(只看上次检查开始之后)'), done=lidx(S(4), '窗口往前重叠 1000 ms'), b=bars([['不重叠:漏掉的改动', 101, '101 / 300'], ['重叠 100 ms:漏掉的改动', 40, '40'], ['重叠 300 ms:漏掉的改动', 9, '9'], ['重叠 1000 ms:漏掉的改动', 0, '0']], 101, mark=[0], cur=[1, 2], done=[3]), kv=KV([['不重叠', '漏掉 33.7%'], ['重叠 ≥ 最长事务时长', '0 漏报'], ['更稳的位点', 'binlog 位点 / LSN,不用 updated_at']], ['更稳的位点'])),
    step("抽样校验。从 100 万行里按 A 的 id 随机抽 n 行比对;第二节注入的 50 处差异里,B 里多出来的 15 行在 A 里没有对应的 id,按 A 的 id 抽不到,只统计另外 35 处。抽 1000 行(0.1%):300 次里 14 次抽到至少一处差异(5%,理论 3%);抽 10000 行(1.0%):96 次(32%,理论 30%);抽 100000 行(10.0%):290 次(97%,理论 97%);抽 500000 行(50.0%):300 次(100%)。差异只占总量的万分之几时,抽样要抽到很大的比例才有把握,罕见的错误靠抽样找不出来;按 A 的 id 抽样还看不到 B 里“多出来”的行。", t=tl(S(5)), mark=lidx(S(5), '1000   |', '10000  |'), done=lidx(S(5), '100000 |', '500000 |'), b=bars([['抽 0.1%:发现概率 %', 5, '5%'], ['抽 1.0%:发现概率 %', 32, '32%'], ['抽 10.0%:发现概率 %', 97, '97%'], ['抽 50.0%:发现概率 %', 100, '100%']], 100, mark=[0, 1], done=[2, 3]), kv=KV([['抽 1%', '只有 32% 的概率发现'], ['抽 10%', '97%'], ['盲区', '按 A 的 id 抽样看不到 B 多出的行']], ['盲区'])),
]
A = mkartt('t31', 31, '分布式事务,数据一致性校验,校验和,增量校验,抽样,MySQL,真实验证,动画演示',
    '100 万行的两个库跨库校验:count / sum 会漏一加一减;分桶校验和 1.67 s、传输 1095 KiB 发现全部 50 处差异(全量比较 3.6 s、31.4 MiB);各种汇总方式的盲区;updated_at 增量窗口不重叠会漏 33.7%;抽 1% 行只有 32% 的概率发现 35 处差异。',
    '跨服务的数据校验怎么做才又快又不漏?比总数够吗?全量比较要传多少数据?分桶校验和怎么省?增量、抽样各有什么坑?这篇用两个各有 100 万行的 MySQL,把这几种校验方法的发现能力和代价量出来。',
    [('1.67 s vs 3.6 s', '分桶校验和与全量比较发现全部 50 处差异所用的时间(传输量 1095 KiB 对 31.4 MiB)'), ('33.7%', '增量校验窗口不重叠时,300 个改动里被漏掉的比例(重叠 1 秒是 0)'), ('32%', '从 100 万行里抽 1% 做校验,发现 35 处差异中至少一处的概率')],
    [('总数校验的盲区', '<p>count 和 sum 对一加一减、只改状态这类错误完全看不出。</p>'),
     ('分桶校验和', '<p>在库里按桶算 count 与行哈希,只传校验和,只下钻有差异的桶:用时和传输量都小得多,发现率不降。</p>'),
     ('哪种汇总能发现什么', '<p>count、sum 管不了的情形,行哈希能管;bit_xor 偶尔漏(CRC 线性),sum 或 SHA-256 链更稳。</p>'),
     ('增量校验', '<p>updated_at 不是提交时刻,事务提交晚的行会漏;窗口要重叠,或者用提交顺序单调的位点。</p>'),
     ('抽样校验', '<p>罕见错误要抽到很大比例才有把握,还看不到另一边多出来的行。</p>')],
    steps,
    [ENV_T + '。本篇用两个独立的 MySQL 26.7.0 实例(各 100 万行的 orders 表);行哈希是 crc32(concat_ws("|", id, amount, status)),分桶 = 每 1000 个 id 一个桶,校验和在库内用 GROUP BY 算;第三节的“造差异”是对 id 1 到 20000 这一段的行改一次、测一次、还原一次;第四节的检查器与 300 个事务是我写的线程,不是真实业务;抽样用的是均匀随机抽 id',
     '没有验证:两个库跨网络时传输时间(这里在同一台机器上,只统计字节数);校验时源库仍在写入的快照一致性(本篇校验期间没有写入);更大的表(亿级)上校验和的计算成本与对主库的影响;Merkle 树多层下钻的最优桶大小(只试了 1000);bit_xor 漏报的原因(CRC 线性)只是解释,没有单独验证;没有主键的明细表里重复行互相抵消的情形(带主键的表里不会出现)'],
    '数据一致性校验')
